import requests, time

def call_api(payload):
    while True:
        session = requests.Session()
        resp = session.post(URL, json=payload, headers=AUTH, timeout=30)
        if resp.status_code == 200:
            return resp.json()
        time.sleep(1)

def run(records):
    out = []
    for r in records:
        out.append(call_api(r))
    return out
